def copiar_propietarios(apps, schema_editor):
    """The single owner of each listing becomes a link; an owner of a large-holder listing is a large holder."""
    DatosInternos = apps.get_model('base', 'DatosInternos')
    InmueblePropietario = apps.get_model('base', 'InmueblePropietario')
    for datos in DatosInternos.objects.exclude(propietario=None).select_related('inmueble', 'propietario'):
        InmueblePropietario.objects.get_or_create(
            inmueble_id=datos.inmueble_id, propietario_id=datos.propietario_id
        )
        if datos.inmueble.gran_tenedor and not datos.propietario.gran_tenedor:
            datos.propietario.gran_tenedor = True
            datos.propietario.save(update_fields=['gran_tenedor'])


def volver_a_datos_internos(apps, schema_editor):
    """Back to one owner per listing: the first link; the listing is a large holder if any owner is."""
    InmueblePropietario = apps.get_model('base', 'InmueblePropietario')
    DatosInternos = apps.get_model('base', 'DatosInternos')
    Inmueble = apps.get_model('base', 'Inmueble')
    for link in InmueblePropietario.objects.select_related('propietario').order_by('id'):
        datos, _ = DatosInternos.objects.get_or_create(inmueble_id=link.inmueble_id)
        if datos.propietario_id is None:
            datos.propietario_id = link.propietario_id
            datos.save(update_fields=['propietario'])
        if link.propietario.gran_tenedor:
            Inmueble.objects.filter(pk=link.inmueble_id).update(gran_tenedor=True)


